use std::fs;
use std::io::{ErrorKind, Write};
use std::path::{Path, PathBuf};

use sha2::{Digest, Sha256};

pub const ENVIRONMENT: &str = ".codex/environments/environment.toml";
const HEADER: &str = "# Generated by jt codex init; body-sha256=";
const LEGACY_HEADER: &str =
    "# Generated by jt codex init. Safe to customize; reruns preserve this file.\n";
// Exact setup shipped before integrity-marked environments. A matching header alone
// is never sufficient to claim a user's configuration.
const LEGACY_CODEGRAPH: &str = r#"
if command -v codegraph >/dev/null 2>&1; then
  worktree_root="$(git rev-parse --show-toplevel)"
  main_worktree_root="$(git worktree list --porcelain | sed -n '1s/^worktree //p')"
  if [ -L .codegraph ] || [ -L .codegraph/codegraph.db ]; then
    printf '%s\n' 'Refusing shared CodeGraph symlink; each worktree needs its own database.' >&2
    exit 1
  fi
  if [ ! -f .codegraph/codegraph.db ] \
    && [ "$worktree_root" != "$main_worktree_root" ] \
    && [ -f "$main_worktree_root/.codegraph/codegraph.db" ] \
    && command -v sqlite3 >/dev/null 2>&1; then
    mkdir -p .codegraph
    (cd .codegraph && sqlite3 "$main_worktree_root/.codegraph/codegraph.db" '.backup codegraph.db')
  fi
  if [ -f .codegraph/codegraph.db ]; then
    codegraph sync "$worktree_root"
  else
    codegraph init "$worktree_root"
  fi
else
  printf '%s\n' 'CodeGraph unavailable; existing project index was not prepared.' >&2
fi
"#;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Mode {
    Preserve,
    Check,
    Update,
}

#[derive(Debug, Eq, PartialEq)]
pub enum Outcome {
    Created,
    Preserved,
    Current,
    Preview { candidate: PathBuf, managed: bool },
    Updated { backup: PathBuf },
    Protected { candidate: PathBuf },
}

pub fn managed(body: &str) -> String {
    format!("{HEADER}{:x}\n{body}", Sha256::digest(body.as_bytes()))
}

pub fn preserve_existing(root: &Path) -> Result<bool, String> {
    inspect(root)?;
    Ok(root.join(ENVIRONMENT).is_file())
}

pub fn apply(root: &Path, rendered: &str, mode: Mode) -> Result<Outcome, String> {
    apply_before_update(root, rendered, mode, || {})
}

fn apply_before_update(
    root: &Path,
    rendered: &str,
    mode: Mode,
    before_update: impl FnOnce(),
) -> Result<Outcome, String> {
    inspect(root)?;
    let path = root.join(ENVIRONMENT);
    let current = match fs::read(&path) {
        Ok(content) => Some(content),
        Err(error) if error.kind() == ErrorKind::NotFound => None,
        Err(error) => return Err(format!("cannot read {}: {error}", path.display())),
    };
    if current.is_some() && mode == Mode::Preserve {
        return Ok(Outcome::Preserved);
    }
    if current.as_deref() == Some(rendered.as_bytes()) {
        return Ok(Outcome::Current);
    }
    let directory = root.join(".codex/environments");
    fs::create_dir_all(&directory).map_err(|error| error.to_string())?;
    inspect(root)?;
    let Some(current) = current else {
        if mode == Mode::Check {
            return Ok(Outcome::Preview {
                candidate: candidate(root, rendered)?,
                managed: true,
            });
        }
        write_new(&path, rendered.as_bytes(), None)?;
        return Ok(Outcome::Created);
    };
    let managed = std::str::from_utf8(&current)
        .is_ok_and(|content| integrity_matches(content) || legacy_matches(root, content));
    if mode == Mode::Check {
        return Ok(Outcome::Preview {
            candidate: candidate(root, rendered)?,
            managed,
        });
    }
    if !managed {
        return Ok(Outcome::Protected {
            candidate: candidate(root, rendered)?,
        });
    }
    before_update();
    let backup = replace(root, &current, rendered.as_bytes())?;
    Ok(Outcome::Updated { backup })
}

fn integrity_matches(content: &str) -> bool {
    let Some((digest, body)) = content
        .strip_prefix(HEADER)
        .and_then(|content| content.split_once('\n'))
    else {
        return false;
    };
    digest == format!("{:x}", Sha256::digest(body.as_bytes()))
}

fn legacy_matches(root: &Path, content: &str) -> bool {
    let name = root
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("project");
    let name = serde_json::to_string(name)
        .unwrap()
        .replace('\u{7f}', "\\u007f");
    let prefix = format!("{LEGACY_HEADER}version = 1\nname = {name}\n\n[setup]\nscript = '''\n");
    let Some((setup, mut actions)) = content
        .strip_prefix(&prefix)
        .and_then(|rest| rest.split_once("'''\n"))
    else {
        return false;
    };
    let setup = setup.strip_suffix(LEGACY_CODEGRAPH).unwrap_or(setup);
    let manager = match setup {
        "set -eu\n" => "",
        "set -eu\nnpm ci\n" | "set -eu\nnpm install\n" => "npm",
        "set -eu\npnpm install --frozen-lockfile --prefer-offline\n"
        | "set -eu\npnpm install --prefer-offline\n" => "pnpm",
        _ => return false,
    };
    for (label, icon, scripts) in [
        ("Dev", "run", &["dev", "start"][..]),
        (
            "Unit tests",
            "test",
            &["test:unit:run", "test:unit", "test"][..],
        ),
        (
            "Type check",
            "test",
            &["type-check", "typecheck", "type:check"][..],
        ),
    ] {
        if manager.is_empty() {
            break;
        }
        for script in scripts {
            let action = format!(
                "\n[[actions]]\nname = \"{label}\"\nicon = \"{icon}\"\ncommand = \"{manager} run {script}\"\n"
            );
            if let Some(rest) = actions.strip_prefix(&action) {
                actions = rest;
                break;
            }
        }
    }
    actions.is_empty()
}

fn inspect(root: &Path) -> Result<(), String> {
    for relative in [".codex", ".codex/environments", ENVIRONMENT] {
        let path = root.join(relative);
        match fs::symlink_metadata(&path) {
            Ok(metadata) if metadata.file_type().is_symlink() => {
                return Err(format!("refusing symlink: {}", path.display()));
            }
            Ok(metadata) if relative == ENVIRONMENT && !metadata.is_file() => {
                return Err(format!("not a regular file: {}", path.display()));
            }
            Ok(metadata) if relative != ENVIRONMENT && !metadata.is_dir() => {
                return Err(format!("not a directory: {}", path.display()));
            }
            Ok(_) => {}
            Err(error) if error.kind() == ErrorKind::NotFound => {}
            Err(error) => return Err(format!("cannot inspect {}: {error}", path.display())),
        }
    }
    Ok(())
}

fn write_new(
    path: &Path,
    bytes: &[u8],
    permissions: Option<fs::Permissions>,
) -> Result<(), String> {
    let mut file = tempfile::NamedTempFile::new_in(path.parent().unwrap())
        .map_err(|error| error.to_string())?;
    file.write_all(bytes).map_err(|error| error.to_string())?;
    if let Some(permissions) = permissions {
        file.as_file()
            .set_permissions(permissions)
            .map_err(|error| error.to_string())?;
    }
    file.as_file()
        .sync_all()
        .map_err(|error| error.to_string())?;
    file.persist_noclobber(path).map_err(|error| {
        format!(
            "cannot create {} without overwriting: {error}",
            path.display()
        )
    })?;
    sync_directory(path.parent().unwrap())?;
    Ok(())
}

fn sync_directory(path: &Path) -> Result<(), String> {
    #[cfg(unix)]
    fs::File::open(path)
        .and_then(|directory| directory.sync_all())
        .map_err(|error| format!("cannot sync {}: {error}", path.display()))?;
    #[cfg(not(unix))]
    let _ = path;
    Ok(())
}

fn candidate(root: &Path, rendered: &str) -> Result<PathBuf, String> {
    inspect(root)?;
    let mut file = tempfile::Builder::new()
        .prefix("environment.toml.candidate-")
        .suffix(".toml")
        .tempfile_in(root.join(".codex/environments"))
        .map_err(|error| error.to_string())?;
    file.write_all(rendered.as_bytes())
        .and_then(|()| file.as_file().sync_all())
        .map_err(|error| error.to_string())?;
    file.keep()
        .map(|(_, path)| path)
        .map_err(|error| error.to_string())
}

fn replace(root: &Path, expected: &[u8], next: &[u8]) -> Result<PathBuf, String> {
    replace_before_publish(root, expected, next, || {})
}

fn replace_before_publish(
    root: &Path,
    expected: &[u8],
    next: &[u8],
    before_publish: impl FnOnce(),
) -> Result<PathBuf, String> {
    inspect(root)?;
    let path = root.join(ENVIRONMENT);
    if fs::read(&path).map_err(|error| error.to_string())? != expected {
        return Err(format!(
            "configuration concurrently changed: {}",
            path.display()
        ));
    }
    let permissions = fs::metadata(&path)
        .map_err(|error| error.to_string())?
        .permissions();
    let backup_directory = tempfile::Builder::new()
        .prefix("environment.toml.backup-")
        .tempdir_in(path.parent().unwrap())
        .map_err(|error| error.to_string())?;
    let backup = backup_directory.path().join("environment.toml");
    write_new(&backup, expected, Some(permissions.clone()))?;
    // Keep the recovery snapshot before touching the live configuration. Moving the
    // old file, checking its bytes, then publishing without clobbering also protects
    // against concurrent writers replacing the destination after the initial check.
    let backup_directory = backup_directory.keep();
    let displaced = backup_directory.join("concurrent-original.toml");
    inspect(root)?;
    fs::rename(&path, &displaced).map_err(|error| {
        format!(
            "cannot move configuration; backup {}: {error}",
            backup.display()
        )
    })?;
    let result = (|| {
        let metadata = fs::symlink_metadata(&displaced).map_err(|error| error.to_string())?;
        if !metadata.is_file()
            || metadata.file_type().is_symlink()
            || fs::read(&displaced).map_err(|error| error.to_string())? != expected
        {
            return Err("configuration concurrently changed".to_owned());
        }
        before_publish();
        inspect(root)?;
        write_new(&path, next, Some(permissions))
    })();
    if let Err(error) = result {
        // A hard link restores the actual displaced file atomically without replacing
        // a file created by another writer. Both recovery files remain on failure.
        let restored = fs::hard_link(&displaced, &path).is_ok();
        return Err(format!(
            "{error}; original {} at {}; backup {}",
            if restored {
                "restored; recovery copy"
            } else {
                "preserved"
            },
            displaced.display(),
            backup.display()
        ));
    }
    // Keep the displaced inode as well: an editor holding its old file descriptor
    // can finish a write after publication, and that content must remain recoverable.
    sync_directory(&backup_directory)?;
    sync_directory(path.parent().unwrap())?;
    Ok(backup)
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    fn legacy(root: &Path, setup: &str, actions: &str) -> String {
        let name = serde_json::to_string(root.file_name().unwrap().to_str().unwrap()).unwrap();
        format!(
            "{LEGACY_HEADER}version = 1\nname = {name}\n\n[setup]\nscript = '''\nset -eu\n{setup}'''\n{actions}"
        )
    }

    #[test]
    fn preserves_existing_configuration_without_parsing_or_installing() {
        let root = tempdir().unwrap();
        let path = root.path().join(ENVIRONMENT);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(&path, "custom unknown syntax").unwrap();
        assert_eq!(
            apply(root.path(), "new", Mode::Preserve).unwrap(),
            Outcome::Preserved
        );
        assert_eq!(fs::read_to_string(path).unwrap(), "custom unknown syntax");
        assert!(!root.path().join("node_modules").exists());
    }

    #[test]
    fn custom_and_modified_templates_get_unique_candidates() {
        let root = tempdir().unwrap();
        let path = root.path().join(ENVIRONMENT);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        let rendered = managed("version = 1\n");
        for custom in [
            "# THIS IS AUTOGENERATED\nversion = 1\n".to_owned(),
            format!("{LEGACY_HEADER}custom command\n"),
            format!("{rendered}# user edit\n"),
            legacy(root.path(), "echo custom\n", ""),
        ] {
            fs::write(&path, &custom).unwrap();
            let Outcome::Protected { candidate } =
                apply(root.path(), &rendered, Mode::Update).unwrap()
            else {
                panic!("custom configuration was not protected");
            };
            assert_eq!(fs::read_to_string(&path).unwrap(), custom);
            assert_eq!(fs::read_to_string(&candidate).unwrap(), rendered);
            fs::write(&candidate, "reviewed custom candidate").unwrap();
            let Outcome::Protected { candidate: second } =
                apply(root.path(), &rendered, Mode::Update).unwrap()
            else {
                panic!("custom configuration was not protected");
            };
            assert_ne!(candidate, second);
            assert_eq!(
                fs::read_to_string(candidate).unwrap(),
                "reviewed custom candidate"
            );
        }
    }

    #[test]
    fn preview_update_backup_and_recovery_are_idempotent() {
        let root = tempdir().unwrap();
        let old = managed("version = 1\nname = \"before\"\n");
        let new = managed("version = 1\nname = \"after\"\n");
        assert_eq!(
            apply(root.path(), &old, Mode::Preserve).unwrap(),
            Outcome::Created
        );
        let path = root.path().join(ENVIRONMENT);
        let Outcome::Preview { candidate, managed } =
            apply(root.path(), &new, Mode::Check).unwrap()
        else {
            panic!("expected preview");
        };
        assert!(managed);
        assert_eq!(fs::read_to_string(candidate).unwrap(), new);
        assert_eq!(fs::read_to_string(&path).unwrap(), old);
        let Outcome::Updated { backup } = apply(root.path(), &new, Mode::Update).unwrap() else {
            panic!("expected update");
        };
        assert_eq!(fs::read_to_string(&backup).unwrap(), old);
        assert_eq!(fs::read_to_string(&path).unwrap(), new);
        assert_eq!(
            apply(root.path(), &new, Mode::Update).unwrap(),
            Outcome::Current
        );
        fs::copy(backup, &path).unwrap();
        assert_eq!(fs::read_to_string(path).unwrap(), old);
    }

    #[test]
    fn recognizes_full_legacy_template_only() {
        let root = tempdir().unwrap();
        let actions = "\n[[actions]]\nname = \"Dev\"\nicon = \"run\"\ncommand = \"pnpm run dev\"\n\n[[actions]]\nname = \"Unit tests\"\nicon = \"test\"\ncommand = \"pnpm run test:unit:run\"\n";
        let old = legacy(
            root.path(),
            &format!("pnpm install --frozen-lockfile --prefer-offline\n{LEGACY_CODEGRAPH}"),
            actions,
        );
        assert!(legacy_matches(root.path(), &old));
        assert!(!legacy_matches(root.path(), &format!("{old}# user edit\n")));
        assert!(!legacy_matches(
            root.path(),
            &old.replace("pnpm run dev", "npm run dev")
        ));
        assert!(!legacy_matches(
            root.path(),
            &old.replace(".backup codegraph.db", ".backup custom.db")
        ));
        let path = root.path().join(ENVIRONMENT);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(&path, &old).unwrap();
        let Outcome::Updated { backup } =
            apply(root.path(), &managed("version = 1\n"), Mode::Update).unwrap()
        else {
            panic!("legacy template should update");
        };
        assert_eq!(fs::read_to_string(backup).unwrap(), old);
    }

    #[test]
    fn concurrent_change_aborts_before_replacement() {
        let root = tempdir().unwrap();
        let old = managed("old\n");
        apply(root.path(), &old, Mode::Preserve).unwrap();
        let path = root.path().join(ENVIRONMENT);
        let error = apply_before_update(root.path(), &managed("next\n"), Mode::Update, || {
            fs::write(&path, "concurrent customization").unwrap();
        })
        .unwrap_err();
        assert!(error.contains("concurrently changed"));
        assert_eq!(
            fs::read_to_string(path).unwrap(),
            "concurrent customization"
        );
    }

    #[test]
    fn concurrent_destination_creation_is_preserved_with_recovery_snapshot() {
        let root = tempdir().unwrap();
        let old = managed("old\n");
        apply(root.path(), &old, Mode::Preserve).unwrap();
        let path = root.path().join(ENVIRONMENT);
        let error = replace_before_publish(root.path(), old.as_bytes(), b"new", || {
            fs::write(&path, "concurrent destination").unwrap();
        })
        .unwrap_err();
        assert!(error.contains("without overwriting"));
        assert_eq!(fs::read_to_string(&path).unwrap(), "concurrent destination");
        let backup_directory = fs::read_dir(path.parent().unwrap())
            .unwrap()
            .map(|entry| entry.unwrap().path())
            .find(|path| path.is_dir())
            .unwrap();
        assert_eq!(
            fs::read_to_string(backup_directory.join("environment.toml")).unwrap(),
            old
        );
        assert_eq!(
            fs::read_to_string(backup_directory.join("concurrent-original.toml")).unwrap(),
            old
        );
    }

    #[cfg(unix)]
    #[test]
    fn refuses_symlinked_paths_and_concurrent_symlink_swap() {
        use std::os::unix::fs::symlink;
        for relative in [".codex", ".codex/environments", ENVIRONMENT] {
            let root = tempdir().unwrap();
            let outside = tempdir().unwrap();
            let path = root.path().join(relative);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            symlink(outside.path().join("missing"), &path).unwrap();
            assert!(
                apply(root.path(), "new", Mode::Update)
                    .unwrap_err()
                    .contains("symlink")
            );
            assert!(!outside.path().join("missing").exists());
        }
        let root = tempdir().unwrap();
        let outside = tempdir().unwrap();
        let target = outside.path().join("custom.toml");
        fs::write(&target, "outside").unwrap();
        apply(root.path(), &managed("old\n"), Mode::Preserve).unwrap();
        let path = root.path().join(ENVIRONMENT);
        assert!(
            apply_before_update(root.path(), &managed("next\n"), Mode::Update, || {
                fs::remove_file(&path).unwrap();
                symlink(&target, &path).unwrap();
            })
            .unwrap_err()
            .contains("symlink")
        );
        assert_eq!(fs::read_to_string(target).unwrap(), "outside");
    }
}
